solution:
def verify_counts(rows, counts):
    expected = {"WIN":0,"LOSS":0,"DRAW":0,"UNKNOWN":0}
    for row in rows:
        label = row.get("derived")
        if label not in ("WIN","LOSS","DRAW"):
            label = "UNKNOWN"
        expected[label] += 1
    assert counts == expected, "categories must match independently counted labels"
